#!/bin/sh
# -*- coding: utf-8 -*-
"exec" "env" "TANIUM_SENSOR=1" "`pwd`/python27/python" "$0" "$@"

from __future__ import print_function, unicode_literals
import sys
import os
import traceback
try:
    import tanium
except ImportError as e:
	emsg = 'Error locating necessary files. Ensure IC-Python is imported and deployed.'
	sys.exit(emsg)

__author__ = 'Tanium'
__content_name__ = 'SEP Client Virus Definition Revision'
__version__ = '1.0.1.0000'


def get_platform():
    return sys.platform


def mac_sep_avdefrev():
    fAvDefInfo = "/Library/Application Support/Symantec/Silo/NFM/Definitions/virusdefs/definfo.dat"
    if os.path.exists(fAvDefInfo):
        fAvDat = open(fAvDefInfo, "r")
        for line in fAvDat.readlines():
            if "CurDefs=" in line:
                sAvDefRev = line.rpartition('=')[-1].rstrip('\n')
                return sAvDefRev
                fAvDat.close()
                break
    else:
        return "Not Installed"


def linux_sep_avdefrev():
    fAvDefInfo = "/opt/Symantec/virusdefs/definfo.dat"
    if os.path.exists(fAvDefInfo):
        fAvDat = open(fAvDefInfo, "r")
        for line in fAvDat.readlines():
            if "CurDefs=" in line:
                sAvDefRev = line.rpartition('=')[-1].rstrip('\n')
                return sAvDefRev
                fAvDat.close()
                break
    else:
        return "Not Installed"


def sensor_main():
    if get_platform() == 'darwin':
        return mac_sep_avdefrev()
    elif get_platform().startswith('linux'):
        return linux_sep_avdefrev()
    else:
        return "Unsupported platform"


if __name__ == '__main__':
    try:
        r = sensor_main()
    except Exception as e:
        r = traceback.format_exc().replace('\n', '->')
    try:
        tanium.results.add(r)
    except (AttributeError, NameError):
        print(r)

